/**
 * ADMIN 이 기간 안의 ACTIVE 구독을 해지 예약한다. PG 를 부르지 않고 기간 끝(currentPeriod.end)에 청구 없이 끝난다. 갱신 결과를 기다리는 동안에도 받는다 — 확인 중인 갱신이 승인되면 그 기간 끝에, 거절되면 그 자리(UNPAID)에서 끝난다. 같은 requestKey 재전송은 다시 적용하지 않고 지금 상태를 돌려주며, expectedVersion 이 다르면 409 BILLING_STATE_CHANGED.
 * @summary 다음 결제 해지 예약
 */
export const cancelBillingSubscription = async (
  workspaceId: string,
  changeBillingSubscriptionRequest?: ChangeBillingSubscriptionRequest,
  options?: Parameters<typeof apiFetch>[1]
): Promise<cancelBillingSubscriptionResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string]
        )
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<cancelBillingSubscriptionResponse>(
    getCancelBillingSubscriptionUrl(workspaceId),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(changeBillingSubscriptionRequest),
    }
  );
};

